stress_periods = {
    "2020_covid_crash": feb_mar_2020_bars,
    "2021_bull_trend": full_year_2021_bars,
    "2022_choppy_rangebound": full_year_2022_bars,
}

report = {}
for period_name, bars in stress_periods.items():
    env = RealisticBacktestEnv(bars)
    returns, equity = run_evaluation_rollout(model, env)  # from the previous two lessons
    report[period_name] = {
        "sharpe": sharpe_ratio(returns),
        "sortino": sortino_ratio(returns),
        "max_drawdown": max_drawdown(equity),
        "cvar_95": conditional_value_at_risk(returns),
    }
